mapper.select:
SELECT 
FROM client_error ce
JOIN workspace w ON w.id = ce.workspace_id
WHERE w.org_id = #{orgId}
  AND ce.reported_at >= #{since}
  AND ce.reported_at <= #{until}

    AND (
      ce.correlation_id =
        CONVERT(#{untrustedClientAssertedCorrelationHmac} USING ascii) COLLATE ascii_bin
      OR ce.correlation_id =
        CONVERT(#{legacyRawCorrelationId} USING ascii) COLLATE ascii_bin
    )

ORDER BY ce.reported_at ASC, ce.id ASC
LIMIT #{limit}

SELECT 
FROM client_error ce
JOIN workspace w ON w.id = ce.workspace_id
WHERE ce.workspace_id = #{workspaceId}
  AND ce.id > #{afterId}
ORDER BY ce.id
LIMIT #{limit}
